#include <stdlib.h>

typedef long long ll;

int countTriplets(int* nums1, int nums1Size, int* nums2, int nums2Size) {
    int res = 0;

    // Helper function to count triplets where square of elements in arr1 equals product of pairs in arr2
    // arr1Size and arr2Size are sizes of arr1 and arr2 respectively
    // arr1[i]^2 == arr2[j]*arr2[k], j<k
    int countType(int* arr1, int arr1Size, int* arr2, int arr2Size) {
        int count = 0;
        // For each element in arr1, compute square
        // For arr2, we count pairs whose product equals that square
        // Since arr2 length <= 1000, O(n^2) is acceptable

        // To speed up, we can store frequency of elements in arr2
        // But since product can be large, we just do double loop

        for (int i = 0; i < arr1Size; i++) {
            ll sq = (ll)arr1[i] * (ll)arr1[i];
            for (int j = 0; j < arr2Size; j++) {
                for (int k = j + 1; k < arr2Size; k++) {
                    ll prod = (ll)arr2[j] * (ll)arr2[k];
                    if (prod == sq) count++;
                }
            }
        }
        return count;
    }

    res += countType(nums1, nums1Size, nums2, nums2Size);
    res += countType(nums2, nums2Size, nums1, nums1Size);

    return res;
}

